self.addEventListener('install', function (e) {
  e.waitUntil(caches.open(SHELL).then(function (c) { return c.addAll(FILES); }));
});
self.addEventListener('activate', function (e) {
  e.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (k) { return k.indexOf('uaecl-shell-') === 0 && k !== SHELL; }).map(function (k) { return caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }));
});
self.addEventListener('message', function (e) { if (e.data === 'skipWaiting') self.skipWaiting(); });

var trimming = false;
function trimTiles(name, max) {
  if (trimming) return; trimming = true;
  caches.open(name || TILES).then(function (c) {
    return c.keys().then(function (keys) {
      var extra = keys.length - (max || MAX_TILES);
      return Promise.all(keys.slice(0, Math.max(0, extra)).map(function (k) { return c.delete(k); }));
    });
  }).then(function () { trimming = false; }, function () { trimming = false; });
}

self.addEventListener('fetch', function (e) {
  var req = e.request; if (req.method !== 'GET') return;
  var url = new URL(req.url);
  if (url.origin === location.origin) {
    // game shell: cache first, network fallback (navigations fall back to index.html)
    e.respondWith(caches.match(req, { ignoreSearch: true }).then(function (hit) {
      return hit || fetch(req).catch(function () { return req.mode === 'navigate' ? caches.match('./index.html') : Response.error(); });
    }));
    return;
  }
  // product / place photos (Wikimedia): fetched with CORS and cached once, so they also show offline.
  // (A plain <img> fetch is "opaque", which Chrome counts as ~7 MB of storage each; a CORS copy is stored at its real size.)
  // Company logos (Google favicon service) are left to the normal browser cache.
  if (/(^|\.)wikimedia\.org$|(^|\.)wikipedia\.org$/.test(url.hostname)) {
    e.respondWith(caches.open(IMGS).then(function (c) {
      return c.match(req.url).then(function (hit) {
        if (hit) return hit;
        return fetch(req.url, { mode: 'cors', credentials: 'omit' }).then(function (r) {
          if (r && r.ok) { c.put(req.url, r.clone()); trimTiles(IMGS, MAX_IMGS); }
          return r;
        }).catch(function () { return fetch(req); });   // no CORS: load it normally, uncached
      });
    }));
    return;
  }
  if (/arcgisonline\.com|openfreemap\.org|tiles\.|basemaps\.|cartocdn|fonts\.(googleapis|gstatic)/.test(url.hostname)) {
    // map tiles / styles / glyphs: cache first, refresh into the cache from the network
    e.respondWith(caches.open(TILES).then(function (c) {
      return c.match(req).then(function (hit) {
        var net = fetch(req).then(function (r) { if (r && (r.ok || r.type === 'opaque')) { c.put(req, r.clone()); trimTiles(); } return r; });
        if (hit) { net.catch(function () {}); return hit; }
        return net;
      });
    }));
  }
});
